import type { Customer, Opt } from './types';
import { interestSeries, money, rateFor, valueAt } from './engine';

// Recomputes "Your next move" from the customer's current numbers, so it changes whenever
// the forecast inputs, repairs, or payments change. Nothing here is generated by AI.

export type Move = { move: string; msg: string; why: string; guard: string };
export type Line = { id: string; label: string; vals: (number | null)[] };
export type NextMoveResult = { opts: Opt[]; best: Move; lines: Line[]; title: string; sub: string; bestId: string };

const amort = (B: number, r: number, n: number) => (r === 0 ? B / n : (B * r) / (1 - Math.pow(1 + r, -n)));
/** Months until a loan is paid off at this payment, or Infinity if the payment does not cover interest. */
const monthsToPayoff = (B: number, r: number, pay: number) => {
  if (B <= 0) return 0;
  if (r === 0) return Math.ceil(B / pay);
  if (pay <= B * r) return Infinity;
  return Math.ceil(-Math.log(1 - (B * r) / pay) / Math.log(1 + r));
};
const interestAt = (B: number, r: number, pay: number) => {
  const m = monthsToPayoff(B, r, pay);
  return Number.isFinite(m) ? pay * m - B : Infinity;
};

/**
 * @param c      customer with their current edits applied
 * @param base   the data pack record, used only to read the refinance rate offered in the pack
 * @param repair repair cost currently counted in the forecast
 */
export function nextMove(c: Customer, base: Customer, repair: number): NextMoveResult {
  const { a, v } = c;
  const value = v.est_market_value_now;
  return a.contract_type === 'loan' ? loanMove(c, base, repair, value) : leaseMove(c, base, repair, value);
}

function loanMove(c: Customer, base: Customer, repair: number, value: number): NextMoveResult {
  const a = c.a, n = a.months_remaining, B = a.current_balance ?? 0, apr = a.apr ?? 0, r = apr / 1200, P = a.monthly_payment;
  const paying = a.paying !== false;
  // Refinance rate: the pack's offer, derived from the pack's own balance and payment (kept fixed so edits move the result).
  const packRefi = base.opts.find(o => o.id === 'REFI');
  const refiRate = packRefi && base.a.current_balance && packRefi.pay
    ? rateFor(base.a.current_balance, packRefi.pay, base.a.months_remaining) : r;

  const keepInt = interestAt(B, r, P);
  const refiPay = amort(B, refiRate, n);
  const refiInt = refiPay * n - B;
  const extPay = amort(B, r, n + 12);
  const extInt = extPay * (n + 12) - B;
  const extraInt = interestAt(B, r, P + 100);
  const equity = value - B;

  const f = (x: number) => (Number.isFinite(x) ? money(x) : 'not enough to cover interest');
  const opts: Opt[] = [
    { id: 'KEEP', name: 'Keep the loan as is', pay: P, chg: 0, up: 0, vs: 0, ok: paying ? 'Y' : 'Y (restart payments)',
      sum: `Keep paying ${money(P)}/mo for ${n} more months. About ${f(keepInt)} of interest remains.` },
    refiRate < r
      ? { id: 'REFI', name: 'Refinance with Toyota Financial Services', pay: refiPay, chg: refiPay - P, up: 0, vs: refiInt - keepInt, ok: 'Y',
          sum: `Refinance ${money(B)} at ${(refiRate * 1200).toFixed(2)}% APR for ${n} months: ${money(refiPay)}/mo, about ${money(Math.abs(keepInt - refiInt))} ${refiInt < keepInt ? 'less' : 'more'} interest.` }
      : { id: 'REFI', name: 'Refinance with Toyota Financial Services', pay: null, chg: null, up: 0, vs: null, ok: 'No lower rate',
          sum: `Your ${apr}% rate is already at or below the ${(refiRate * 1200).toFixed(2)}% offer, so refinancing would not lower your interest.` },
    { id: 'EXTEND', name: 'Extend the term by 12 months', pay: extPay, chg: extPay - P, up: 0, vs: extInt - keepInt, ok: r > 0 ? 'Y' : 'N',
      sum: `Lower payment to ${money(extPay)}/mo (${extPay - P < 0 ? '-' : '+'}${money(Math.abs(extPay - P))}) but about ${money(Math.abs(extInt - keepInt))} ${extInt > keepInt ? 'more' : 'less'} interest.` },
    { id: 'EXTRA100', name: 'Pay $100 extra per month', pay: P + 100, chg: 100, up: 0, vs: extraInt - keepInt, ok: paying ? 'Y' : 'N (payments stopped)',
      sum: Number.isFinite(extraInt) ? `Paying ${money(P + 100)}/mo saves about ${money(Math.abs(keepInt - extraInt))} in interest and finishes ${Math.max(0, monthsToPayoff(B, r, P) - monthsToPayoff(B, r, P + 100))} months sooner.` : 'Not enough to cover interest right now.' },
  ];
  if (repair > 0) opts.push({ id: 'REPAIR', name: 'Repair now', pay: null, chg: null, up: repair, vs: null, ok: 'Y', sum: `Repairs counted in your forecast: ${money(repair)}.` });
  opts.push({ id: 'SELL', name: 'Sell or trade in', pay: null, chg: null, up: 0, vs: equity, ok: equity >= 0 ? 'Y' : 'Caution (negative equity)',
    sum: equity >= 0 ? `Worth about ${money(value)} against ${money(B)} owed: about ${money(equity)} left after payoff.` : `Worth about ${money(value)} against ${money(B)} owed: you would owe about ${money(-equity)} more.` });

  // Choose the best finance path: lowest interest among eligible options, if it saves at least $100.
  const finance = opts.filter(o => ['KEEP', 'REFI', 'EXTEND', 'EXTRA100'].includes(o.id) && o.ok.startsWith('Y'));
  const cost = (o: Opt) => (o.id === 'KEEP' ? keepInt : o.id === 'REFI' ? refiInt : o.id === 'EXTEND' ? extInt : extraInt);
  let bestOpt = finance.reduce((best, o) => (cost(o) < cost(best) ? o : best), finance[0]);
  if (!bestOpt || cost(bestOpt) > keepInt - 100) bestOpt = opts.find(o => o.id === 'KEEP')!;

  let bestId = bestOpt.id;
  const repairHeavy = repair > 0.25 * value;
  if (repairHeavy && equity >= 0) bestId = 'SELL';
  if (!paying) bestId = 'KEEP';

  const names: Record<string, string> = { KEEP: 'Keep your loan as it is', REFI: 'Refinance your loan', EXTEND: 'Extend your term', EXTRA100: 'Pay $100 extra each month', SELL: 'Sell or trade in now' };
  const others = opts.filter(o => o.id !== bestId && ['KEEP', 'REFI', 'EXTEND', 'EXTRA100'].includes(o.id)).map(o => `${o.name.toLowerCase()}: ${o.sum}`).join(' ');
  let msg: string, why: string;
  if (!paying) {
    msg = `Your payments are not being made, so the balance is growing with interest. Restarting payments of ${money(P)}/mo stops that.`;
    why = `Missed payments add interest every month. ${others}`;
  } else if (bestId === 'SELL') {
    msg = `Repairs of ${money(repair)} are more than a quarter of the car's value of ${money(value)}. Selling while you still have ${money(Math.max(0, equity))} of equity is the stronger move.`;
    why = `Keeping the car means paying for these repairs and continued interest. ${opts.find(o => o.id === 'SELL')!.sum}`;
  } else if (bestId === 'KEEP') {
    msg = `Keep paying ${money(P)}/mo. Your balance of ${money(B)} at ${apr}% has about ${f(keepInt)} of interest left, and none of the other options saves much more than that.`;
    why = `Each alternative changes your interest by at least ${money(Math.min(...[refiInt - keepInt, extInt - keepInt].filter(x => Number.isFinite(x)).map(Math.abs)))}, and none is clearly better. ${others}`;
  } else {
    const o = opts.find(x => x.id === bestId)!;
    msg = `${o.sum} This is the lowest-interest path with your current balance and payment.`;
    why = `Keeping the loan as is leaves about ${f(keepInt)} of interest. ${others}`;
  }
  if (repair > 0 && !repairHeavy && paying) why += ` Your repairs (${money(repair)}) are counted in the forecast on every path that keeps the car.`;

  const guard = !c.consent || c.vuln ? c.best.guard : 'These are estimates from your numbers, not offers. Confirm rates and fees with Toyota Financial Services.';
  const H = Math.max(12, Math.min(72, n + 12));
  const lines: Line[] = [];
  const pushLine = (id: string, label: string, vals: number[]) => { if (!opts.find(o => o.id === id && o.ok.startsWith('Y'))) return; lines.push({ id, label, vals: vals.map(x => (Number.isFinite(x) ? Math.round(x) : 0)) }); };
  const keepVals = interestSeries(B, r, P, H), refiVals = interestSeries(B, refiRate, refiPay, H), extVals = interestSeries(B, r, extPay, H), extraVals = interestSeries(B, r, P + 100, H);
  pushLine('KEEP', 'Keep as is', keepVals);
  pushLine('REFI', 'Refinance', refiVals);
  pushLine('EXTEND', 'Extend term', extVals);
  pushLine('EXTRA100', 'Pay $100 extra', extraVals);

  return {
    opts, bestId, lines, title: 'Interest you pay under each option', sub: 'Lower is better. Lines update when your balance, payment, rate or repairs change. Click a card to show or hide its line.',
    best: { move: names[bestId] ?? names.KEEP, msg, why, guard },
  };
}

function leaseMove(c: Customer, base: Customer, repair: number, value: number): NextMoveResult {
  const a = c.a, n = a.months_remaining, resid = a.residual_value ?? 0, P = a.monthly_payment;
  const buyout = value - resid;
  const packReturn = base.opts.find(o => o.id === 'RETURN');
  const packRenew = base.opts.find(o => o.id === 'RENEW');
  const fee = packReturn?.up ?? 0;

  const opts: Opt[] = [
    { id: 'KEEP', name: 'Keep the lease', pay: P, chg: 0, up: 0, vs: 0, ok: 'Y', sum: `Keep paying ${money(P)}/mo for ${n} more months.` },
    { id: 'BUYOUT', name: 'Buy the car at lease end', pay: null, chg: null, up: resid, vs: buyout, ok: 'Y',
      sum: buyout >= 0 ? `Buyout ${money(resid)}. The car is worth about ${money(value)}, so you would be about ${money(buyout)} ahead.` : `Buyout ${money(resid)} is more than the car is worth (about ${money(value)}).` },
    { id: 'RETURN', name: 'Return the car at lease end', pay: null, chg: null, up: fee, vs: -fee, ok: 'Y', sum: `Return fees about ${money(fee)} plus any excess mileage.` },
  ];
  if (packRenew) opts.push({ ...packRenew, ok: packRenew.ok });
  if (repair > 0) opts.push({ id: 'REPAIR', name: 'Repair now', pay: null, chg: null, up: repair, vs: null, ok: 'Y', sum: `Repairs counted in your forecast: ${money(repair)}.` });

  let bestId = buyout > fee ? 'BUYOUT' : 'RETURN';
  if (repair > 0.25 * value) bestId = 'RETURN';
  const best: Move = bestId === 'BUYOUT'
    ? { move: 'Buy the car at lease end', msg: `The car is worth about ${money(value)} against a ${money(resid)} buyout, so buying is worth about ${money(buyout)} to you.`, why: `Returning the car costs about ${money(fee)} in fees and gives you nothing back. ${opts.find(o => o.id === 'KEEP')!.sum}`, guard: c.best.guard }
    : { move: 'Return the car at lease end', msg: `Buying would cost ${money(resid)} for a car worth about ${money(value)}${repair > 0 ? ', and repairs of ' + money(repair) + ' are counted' : ''}. Returning is the simpler choice.`, why: `Return fees are about ${money(fee)}. ${opts.find(o => o.id === 'BUYOUT')!.sum}`, guard: c.best.guard };

  const H = n + 18;
  const lines: Line[] = [];
  const series = (f: (t: number) => number) => Array.from({ length: H + 1 }, (_, t) => (t < n ? 0 : Math.round(f(t))));
  lines.push({ id: 'BUYOUT', label: 'Buy the car', vals: series(t => valueAt(c, t, c.v.annual_miles_est) - resid) });
  lines.push({ id: 'RETURN', label: 'Return the car', vals: series(() => -fee) });
  if (packRenew?.up != null) lines.push({ id: 'RENEW', label: 'Renew early', vals: series(() => -(packRenew.up ?? 0)) });

  return {
    opts, bestId, lines, title: 'Your cash position after the lease ends',
    sub: 'Above zero means you come out ahead. Buying is the car\'s value minus the buyout price; returning costs the turn-in and mileage fees. Lines update with your numbers.',
    best,
  };
}
